source_code_context:
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>

enum release_cause {
    RELEASE_CAUSE_NONE,
    RELEASE_CAUSE_NETWORK
};

enum ue_state {
    UE_CONNECTED,
    UE_IDLE
};

struct ue_ctx {
    bool release_pending;
    enum release_cause release_cause;
    uint8_t release_transaction_id;
    enum ue_state state;
};

extern int send_release_complete(struct ue_ctx *ue);

int complete_ue_context_release(struct ue_ctx *ue, bool transmit_complete)
{
    if (ue == NULL) {
        return -EINVAL;
    }

    if (transmit_complete) {
        int rc = send_release_complete(ue);
        if (rc != 0) {
            return rc;
        }
        ue->release_pending = false;
        ue->release_cause = RELEASE_CAUSE_NONE;
        ue->release_transaction_id = 0;
        ue->state = UE_IDLE;
        return 0;
    }

    ue->release_pending = false;
    ue->release_cause = RELEASE_CAUSE_NONE;
    ue->release_transaction_id = 0;
    ue->state = UE_IDLE;
    return 0;
}
